#!/bin/bash
# Generated by reef-eval's EdgeBench converter. Runs in the SEPARATE verifier
# container (built from the judge image). Harbor re-materializes the declared
# submission artifacts at their original paths before this script runs; the
# checks below just make a missing submission loud.
set -uo pipefail
mkdir -p /logs/verifier

[ -e "/home/workspace/train.py" ] || echo "WARNING: submission missing: /home/workspace/train.py"
[ -e "/home/workspace/infer.py" ] || echo "WARNING: submission missing: /home/workspace/infer.py"
[ -e "/home/workspace/models" ] || echo "WARNING: submission missing: /home/workspace/models"
[ -e "/home/workspace/submission.json" ] || echo "WARNING: submission missing: /home/workspace/submission.json"
[ -e "/home/workspace/requirements.txt" ] || echo "WARNING: submission missing: /home/workspace/requirements.txt"
[ -e "/home/workspace/README.md" ] || echo "WARNING: submission missing: /home/workspace/README.md"

cd /home/workspace
OUT=$(cd /home/workspace && python3 scoring/score.py 2>&1)
EC=$?
echo "$OUT" | tail -40
printf '%s' "$OUT" | python3 /tests/parse_score.py
echo "eval exit code: $EC" > /logs/verifier/eval_exit_code.txt
